mapper.select:
SELECT qna_no, parent_no, type, subject, content, status, id, is_secret, created_at, goods_no
 FROM qna
 WHERE qna_no = #{qna_no}

mapper.update:
UPDATE qna SET
type=#{type},
subject=#{subject},
content=#{content},
is_secret=#{is_secret}
WHERE qna_no=#{qna_no}

mapper.select:
  SELECT qna_no, parent_no, type, subject, content, status, id, is_secret, TO_CHAR(CREATED_AT, 'yyyy-mm-dd') AS dbday, goods_no
		FROM qna
		WHERE qna_no = #{parent_no}
